from itertools import product
samples=[(7,10,28,24),(8,9,31,8),(6,13,0,17)]
# search linear modular forms a*s+b*d+c mod 32, and mod31 mapped 31
for target_idx in [2,3]:
    sols=[]
    for a,b,c in product(range(32),repeat=3):
        if all((a*s+b*d+c)%32==sample[target_idx] for s,d,*rest in samples for sample in [(s,d,*rest)]):
            sols.append((a,b,c))
    print(target_idx,sols[:20])

for mod in [31,32,33]:
 for ti in [2,3]:
  sols=[]
  for a,b,c,d0,e in product(range(mod),repeat=5):
   if all((a*s+b*dd+c*s*dd+d0*s*s+e*dd*dd+1)%mod==sam[ti]%mod for sam in samples for s,dd in [sam[:2]]):
    sols.append((a,b,c,d0,e))
    if len(sols)>2:break
  print(mod,ti,sols[:2])

for mod in [31,32]:
 for ti in [2,3]:
  sols=[]
  for a,b,c,k in product(range(mod),repeat=4):
   if all((a*s+b*d+c*s*d+k)%mod==sam[ti] for sam in samples for s,d in [sam[:2]]):
    sols.append((a,b,c,k))
    if len(sols)>=5:break
  print(mod,ti,sols)

# coords r,c
cs=[(1,3,2,2,28,24),(2,0,2,1,31,8),(1,2,3,1,0,17)]
for mod in [31,32]:
 for oi in [4,5]:
  sols=[]
  # coeff rA,cA,rB,cB,k
  for a,b,c,d,k in product(range(mod),repeat=5):
   if all((a*ra+b*ca+c*rb+d*cb+k)%mod==sam[oi] for sam in cs for ra,ca,rb,cb in [sam[:4]]):
    sols.append((a,b,c,d,k))
    if len(sols)>=3:break
  print(mod,oi,sols)

for mod in [31,32]:
 sols=[]
 for a,b,c,d,k in product(range(mod),repeat=5):
  if all((a*ra+b*ca+c*rb+d*cb+k)%mod==sam[5] for sam in cs for ra,ca,rb,cb in [sam[:4]]):
   sols.append((sum(min(x,mod-x) for x in [a,b,c,d,k]),(a,b,c,d,k)))
 print(mod,sorted(sols)[:20])
